class ImmutableMoney {
    private final double amount;
    private final String currency;

    public ImmutableMoney(double amount, String currency) {
        if (amount < 0) throw new IllegalArgumentException("Amount cannot be negative");
        this.amount = amount;
        this.currency = (currency != null) ? currency : "USD";
    }

    public double getAmount() { return amount; }
    public String getCurrency() { return currency; }

    public ImmutableMoney add(double more) {
        return new ImmutableMoney(this.amount + more, this.currency);
    }
}

public class EncapsulationDemo {
    public static void main(String[] args) {
        ImmutableMoney wallet = new ImmutableMoney(50.0, "USD");
        ImmutableMoney updated = wallet.add(25.0);

        System.out.println("Original: $" + wallet.getAmount());
        System.out.println("Updated: $" + updated.getAmount());
    }
}

