interface Notification {
    void send(String message);

    static Notification createEmail(String recipient) {
        return new EmailNotification(recipient);
    }
}

class EmailNotification implements Notification {
    private final String recipient;
    EmailNotification(String recipient) {
        this.recipient = recipient;
    }
    public void send(String message) {
        System.out.println("Email to " + recipient + ": " + message);
    }
}

public class NotificationFactoryDemo {
    public static void main(String[] args) {
        Notification n = Notification.createEmail("user@example.com");
        n.send("Welcome!");
    }
}

