import java.util.*;

public class TeamRosterDemo {
    static class TeamRoster {
        private final List<String> players = new ArrayList<>();

        public void addPlayer(String name) {
            if (name != null) players.add(name);
        }

        public List<String> getPlayers() {
            return Collections.unmodifiableList(players);
        }
    }

    public static void main(String[] args) {
        TeamRoster team = new TeamRoster();
        team.addPlayer("Lionel");
        team.addPlayer("Cristiano");
        System.out.println("Team size: " + team.getPlayers().size());
        try {
            team.getPlayers().add("Neymar");
        } catch (UnsupportedOperationException e) {
            System.out.println("Protected: Cannot modify list from outside!");
        }
    }
}
